const recentNotices=[];let toastTimer;function toast(text){recentNotices.push({time:new Date().toISOString(),message:String(text).slice(0,1500)});if(recentNotices.length>20)recentNotices.shift();if(!lastSaveOK)text="Changes are only in memory: storage is unavailable. Export your work before closing.";$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function modal(title,body,closable=true){if(!startupReady){pendingModal=()=>modal(title,body,closable);return;}$('#sheet-content').innerHTML=`<div class="sheet-heading"><h2>${title}</h2>${closable?`<button class="icon-button" data-action="close" aria-label="Close">${icon('close')}</button>`:''}</div>${body}`;sheet.dataset.locked=closable?'false':'true';if(!sheet.open)sheet.showModal();}
