document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){const action=actions[el.dataset.action];if(action)action(el);}});
document.addEventListener('input',e=>{if(e.target.id==='journal-text')journalInput();if(e.target.id==='place-search')filterPlaces();if(e.target.id==='search-saved')searchSaved(e.target.value);});
