if(form.id==='delete-form'){if(formValue(form,'code')!==form.dataset.code)return toast('The confirmation code does not match.');const id=data.profile.id,groups=data.groups.map(g=>leaveGroup(g,id)),pins=data.pins.filter(p=>p.scope!=='personal'),routes=data.routes.filter(r=>r.scope!=='personal');const replacement=freshState();replacement.groups=groups;replacement.pins=pins;replacement.routes=routes;try{saveState(replacement);}catch{return toast('Could not delete local data. Check browser storage settings.');}data=replacement;scope='personal';activeGroup=null;photoDraft=null;gpsTracker?.stop();gpsTracker=null;gpsIssue='';watch=null;location=null;following=false;if(you)map.removeLayer(you);if(accuracyCircle)map.removeLayer(accuracyCircle);you=accuracyCircle=null;$('#gps-title').textContent='Find your bearings';$('#gps-detail').textContent='Enable GPS to see your position';$('#gps-button').textContent='Enable GPS';close();navigate('map');onboarding();}
