window.addEventListener('offline',()=>{$('#connection').textContent='Offline · local notes';toast('Offline. Your saved notes are here; new map imagery needs a connection.');});window.addEventListener('online',()=>{$('#connection').innerHTML='<span class="signal-dot"></span> Device only';});
